class Solution:
    def checkContradictions(self, equations, values):
        par, rel = {}, {}
        def find(x):
            if x not in par:
                par[x] = x
                rel[x] = 1.0
                return x, 1.0
            if par[x] == x:
                return x, 1.0
            r, rr = find(par[x])
            par[x] = r
            rel[x] *= rr
            return r, rel[x]
        for (a, b), v in zip(equations, values):
            ra, xa = find(a)
            rb, xb = find(b)
            if ra == rb:
                if abs(xa / xb - v) > 1e-5:
                    return True
            else:
                par[ra] = rb
                rel[ra] = v * xb / xa
        return False

