class Solution {
    private Map<String,String> par = new HashMap<>();
    private Map<String,Double> rel = new HashMap<>();
    private String[] find(String x) {
        if (!par.containsKey(x)) { par.put(x, x); rel.put(x, 1.0); return new String[]{x, null}; }
        if (par.get(x).equals(x)) return new String[]{x, "1.0"};
        String[] p = find(par.get(x));
        par.put(x, p[0]);
        rel.put(x, rel.get(x) * Double.parseDouble(p[1]));
        return new String[]{p[0], String.valueOf(rel.get(x))};
    }
    public boolean checkContradictions(List<List<String>> equations, double[] values) {
        for (int i = 0; i < equations.size(); i++) {
            String a = equations.get(i).get(0), b = equations.get(i).get(1);
            double v = values[i];
            String[] fa = find(a), fb = find(b);
            double xa = Double.parseDouble(fa[1]), xb = Double.parseDouble(fb[1]);
            if (fa[0].equals(fb[0])) {
                if (Math.abs(xa / xb - v) > 1e-5) return true;
            } else {
                par.put(fa[0], fb[0]);
                rel.put(fa[0], v * xb / xa);
            }
        }
        return false;
    }
}

