from collections import deque, defaultdict
class Solution:
    def checkContradictions(self, equations, values):
        adj = defaultdict(list)
        nodes = set()
        for (a, b), v in zip(equations, values):
            adj[a].append((b, v))
            adj[b].append((a, 1.0 / v))
            nodes.add(a); nodes.add(b)
        val = {}
        for s in nodes:
            if s in val: continue
            val[s] = 1.0
            q = deque([s])
            while q:
                u = q.popleft()
                for w, wt in adj[u]:
                    if w not in val:
                        val[w] = val[u] * wt
                        q.append(w)
        for (a, b), v in zip(equations, values):
            if abs(val[a] / val[b] - v) > 1e-5:
                return True
        return False

