class Solution {
public:
    bool checkContradictions(vector<vector<string>>& equations, vector<double>& values) {
        unordered_map<string, vector<pair<string,double>>> adj;
        unordered_map<string,double> val;
        for (int i = 0; i < (int)equations.size(); i++) {
            auto& e = equations[i]; double v = values[i];
            adj[e[0]].push_back({e[1], v});
            adj[e[1]].push_back({e[0], 1.0 / v});
        }
        for (auto& [s, _] : adj) {
            if (val.count(s)) continue;
            val[s] = 1.0;
            queue<string> q; q.push(s);
            while (!q.empty()) {
                auto u = q.front(); q.pop();
                for (auto& [w, wt] : adj[u]) {
                    if (!val.count(w)) { val[w] = val[u] * wt; q.push(w); }
                }
            }
        }
        for (int i = 0; i < (int)equations.size(); i++) {
            auto& e = equations[i];
            if (fabs(val[e[0]] / val[e[1]] - values[i]) > 1e-5) return true;
        }
        return false;
    }
};

