class Solution {
    public boolean checkContradictions(List<List<String>> equations, double[] values) {
        Map<String, List<Object[]>> adj = new HashMap<>();
        Map<String, Double> val = new HashMap<>();
        for (int i = 0; i < equations.size(); i++) {
            String a = equations.get(i).get(0), b = equations.get(i).get(1);
            double v = values[i];
            adj.computeIfAbsent(a, k -> new ArrayList<>()).add(new Object[]{b, v});
            adj.computeIfAbsent(b, k -> new ArrayList<>()).add(new Object[]{a, 1.0 / v});
        }
        for (String s : adj.keySet()) {
            if (val.containsKey(s)) continue;
            val.put(s, 1.0);
            Queue<String> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty()) {
                String u = q.poll();
                for (Object[] ed : adj.get(u)) {
                    String w = (String) ed[0]; double wt = (Double) ed[1];
                    if (!val.containsKey(w)) { val.put(w, val.get(u) * wt); q.offer(w); }
                }
            }
        }
        for (int i = 0; i < equations.size(); i++) {
            String a = equations.get(i).get(0), b = equations.get(i).get(1);
            if (Math.abs(val.get(a) / val.get(b) - values[i]) > 1e-5) return true;
        }
        return false;
    }
}

